import { Card, CardBody } from '@zyxui/card';
import Text from '@zyxui/text';
import Button from '@zyxui/button';
import Badge from '@zyxui/badge';

export const Notification = ({ notification }) => {
  const data = notification || {
    type: 'info',
    title: 'New Update Available',
    message: 'Version 2.0 is now available with new features and improvements.',
    timestamp: '2 minutes ago'
  };

  const getColor = (type) => {
    const colors = {
      success: 'success',
      warning: 'warning',
      danger: 'danger',
      info: 'primary'
    };
    return colors[type] || 'primary';
  };

  return (
    <Card className="max-w-md">
      <CardBody>
        <div className="flex items-start space-x-3">
          <Badge 
            dot 
            color={getColor(data.type)} 
            className="mt-2"
          />
          <div className="flex-1">
            <div className="flex justify-between items-start mb-1">
              <Text as="h4" className="font-semibold">
                {data.title}
              </Text>
              <Text className="text-xs text-muted-foreground">
                {data.timestamp}
              </Text>
            </div>
            <Text className="text-sm text-muted-foreground mb-3">
              {data.message}
            </Text>
            <div className="flex gap-2">
              <Button size="sm">View</Button>
              <Button variant="ghost" size="sm">Dismiss</Button>
            </div>
          </div>
        </div>
      </CardBody>
    </Card>
  );
};

